@push('scripts')<script src="https://code.jquery.com/jquery-3.7.1.min.js"></script><script src="https://cdn.jsdelivr.net/npm/select2@4.1.0-rc.0/dist/js/select2.min.js"></script><script>$(function(){const formatar=item=>{if(!item.id)return item.text;const el=item.element,foto=el.dataset.foto,email=el.dataset.email||'Sem e-mail';return $(`<span class="usuario-select2">${foto?`<img src="${$('<div>').text(foto).html()}" referrerpolicy="no-referrer" alt="">`:'<span class="avatar-vazio"><i class="bi bi-person-fill"></i></span>'}<span><strong></strong><small class="d-block text-secondary"></small></span></span>`).find('strong').text(item.text).end().find('small').text(email).end()};$('#usuario_id').select2({theme:'bootstrap-5',width:'100%',allowClear:true,placeholder:'Sem usuário associado',templateResult:formatar,templateSelection:formatar,escapeMarkup:m=>m});});</script>@endpush
